//! A pre-ledger listener store keeps its token and audit rows on adoption.

use std::fs;
use std::os::unix::fs::PermissionsExt;

use orbit_auth::scope::LeaseTokenVerb;
use orbit_auth::store::{LEASE_TOKEN_STORE_FILE, LeaseTokenStore};
use orbit_common::storage::sqlite::ledger;
use rusqlite::{Connection, OpenFlags};

// Generated by the lease token schema code at 2e126bdc5227, with a synthetic
// token row (zero bytes as its dummy hash) and one row in each audit table.
const PRE_LEDGER_STORE: &[u8] = include_bytes!("../fixtures/lease-tokens-v3.db");

#[test]
fn legacy_lease_token_database_adopts_ledger_without_losing_rows()
-> Result<(), Box<dyn std::error::Error>> {
    let home = tempfile::tempdir()?;
    fs::set_permissions(home.path(), fs::Permissions::from_mode(0o700))?;
    let path = home.path().join(LEASE_TOKEN_STORE_FILE);
    fs::write(&path, PRE_LEDGER_STORE)?;
    fs::set_permissions(&path, fs::Permissions::from_mode(0o600))?;

    let store = LeaseTokenStore::open_in_orbit_home(home.path())?;
    let tokens = store.list()?;
    assert_eq!(tokens.len(), 1);
    assert_eq!(tokens[0].token_id, "lt_legacy_fixture");
    assert_eq!(tokens[0].scope.principal, "legacy-user");
    assert_eq!(tokens[0].scope.workspaces, ["ws_legacy"]);
    assert_eq!(tokens[0].scope.verbs, [LeaseTokenVerb::Read]);
    drop(store);

    let connection = Connection::open_with_flags(path, OpenFlags::SQLITE_OPEN_READ_ONLY)?;
    let audit: (String, String, String) = connection.query_row(
        "SELECT event, token_id, actor FROM lease_token_audit WHERE audit_id = 17",
        [],
        |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
    )?;
    assert_eq!(
        audit,
        ("mint".into(), "lt_legacy_fixture".into(), "operator".into())
    );
    let count: i64 = connection.query_row(
        "SELECT count FROM lease_listener_limit_audit WHERE limit_key = 'fixture-key'",
        [],
        |row| row.get(0),
    )?;
    assert_eq!(count, 2);
    let legacy_version: i64 =
        connection.pragma_query_value(None, "user_version", |row| row.get(0))?;
    assert_eq!(legacy_version, 3);
    let applied = ledger::applied_migrations(&connection)?;
    assert_eq!(applied.len(), 1);
    assert_eq!(
        (applied[0].version, applied[0].name.as_str()),
        (1, "lease_token_store_baseline")
    );
    Ok(())
}
